using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Informs TDLib that a Web App is being opened from the attachment menu, a botMenuButton button, an internalLinkTypeAttachmentMenuBot link, or an inlineKeyboardButtonTypeWebApp button.
    /// For each bot, a confirmation alert about data sent to the bot must be shown once
    /// </summary>
    public Task<TdLib.TdApi.Objects.WebAppInfo> OpenWebAppAsync(long chatId = default, long botUserId = default, string url = default, MessageTopic topicId = default, InputMessageReplyTo replyTo = default, WebAppOpenParameters parameters = default)
    {

           using var activity =  StartCallActivity("OpenWebAppAsync", typeof(OpenWebApp).FullName ?? "OpenWebAppAsync");

           try
           {
             return client.OpenWebAppAsync(chatId, botUserId, url, topicId, replyTo, parameters);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
